896	    69	        const score = questionWords.reduce(
897	    70	          (acc, word) => acc + (contentLower.includes(word) ? 1 : 0),
898	    71	          0
899	    72	        );
900	    73	        return { chunk, score };
901	    74	      });
902	    75	
903	    76	      // Take top 2 relevant chunks as citations
904	    77	      const relevant = scored
905	    78	        .filter(s => s.score > 0)
906	    79	        .sort((a, b) => b.score - a.score)
907	    80	        .slice(0, 2);
908	    81	
909	    82	      this.log.info('Keyword matching results', {
910	    83	        questionWords: questionWords.length,
911	    84	        relevantChunks: relevant.length,
912	    85	      });
913	    86	
914	    87	      // Get document metadata for citations
915	    88	      const docs = this.persistence.readJson<Array<{ id: string; title: string }>>('documents-meta.json') ?? [];
916	    89	
917	    90	      for (const { chunk } of relevant) {
918	    91	        const doc = docs.find(d => d.id === chunk.documentId);
919	    92	        citations.push({
920	    93	          documentId: chunk.documentId,
921	    94	          documentTitle: doc?.title ?? 'Unknown Document',
922	    95	          chunkIndex: chunk.index,
923	    96	          excerpt: chunk.content.substring(0, 200),
924	    97	        });
925	    98	      }
926	    99	    }
927	   100	
928	   101	    // Generate answer from mock patterns or use fallback
929	   102	    const answer = this.generateAnswer(question, citations);
930	   103	
931	   104	    const response: QAResponse = {
932	   105	      answer,
933	   106	      citations,
934	   107	      confidence: citations.length > 0 ? 0.85 : 0.3,
935	   108	      timestamp: new Date().toISOString(),
936	   109	    };
937	   110	
938	   111	    this.log.info('Q&A response generated', {
939	   112	      confidence: response.confidence,
940	   113	      citationCount: citations.length,
941	   114	      answerLength: answer.length,
942	   115	    });
943	   116	
944	   117	    // Save to history
945	   118	    this.saveToHistory(question, response);
946	   119	
947	   120	    return response;
948	   121	  }
949	   122	
950	   123	  /** Get the Q&A history. */
951	   124	  getHistory(): QAHistory[] {
952	   125	    return this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE) ?? [];
953	   126	  }
954	   127	
955	   128	  /** Clear the Q&A history. */
956	   129	  clearHistory(): void {
957	   130	    this.persistence.writeJson(QA_HISTORY_FILE, []);
958	   131	    this.log.info('Q&A history cleared');
959	   132	  }
960	   133	
961	   134	  private generateAnswer(question: string, citations: Citation[]): string {
962	   135	    // Match against mock patterns
963	   136	    const questionLower = question.toLowerCase();
964	   137	    for (const pattern of MOCK_PATTERNS) {
965	   138	      if (pattern.keywords.some(kw => questionLower.includes(kw))) {
966	   139	        if (citations.length > 0) {
967	   140	          return `${pattern.answer} Based on the document "${citations[0].documentTitle}", ${citations[0].excerpt.substring(0, 100)}.`;
968	   141	        }
969	   142	        return pattern.answer;
970	   143	      }
971	   144	    }
972	   145	
973	   146	    // Fallback answer
974	   147	    if (citations.length > 0) {
975	   148	      return `Based on the available documents, the most relevant information comes from "${citations[0].documentTitle}": ${citations[0].excerpt.substring(0, 150)}. However, a more specific answer would require additional context.`;
976	   149	    }
977	   150	
978	   151	    return 'No relevant documents have been indexed yet. Please import and index documents before asking questions.';
979	   152	  }
980	   153	
981	   154	  private saveToHistory(question: string, response: QAResponse): void {
982	   155	    const history = this.getHistory();
983	   156	    history.push({ question, response });
984	   157	    this.persistence.writeJson(QA_HISTORY_FILE, history);
985	   158	    this.log.info('Question saved to history', { historyLength: history.length });
986	   159	  }
987	   160	}
