import React, { useState } from 'react';

interface Props {
  onAsk: (question: string) => void;
  /** True while an answer is pending; submissions are ignored until it settles. */
  busy: boolean;
}

export function QuestionPanel({ onAsk, busy }: Props) {
  const [question, setQuestion] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (busy || !question.trim()) return;
    onAsk(question.trim());
    setQuestion('');
  };

  return (
    <form
      onSubmit={handleSubmit}
      aria-label="Ask a question"
      style={{
        display: 'flex',
        padding: '12px 20px',
        borderTop: '1px solid #0f3460',
        background: '#16213e',
      }}
    >
      <label htmlFor="question-input" style={{
        position: 'absolute',
        width: '1px',
        height: '1px',
        overflow: 'hidden',
        clip: 'rect(0 0 0 0)',
        whiteSpace: 'nowrap',
      }}>
        Question about your documents
      </label>
      <input
        id="question-input"
        type="text"
        value={question}
        onChange={e => setQuestion(e.target.value)}
        placeholder="Ask a question about your documents..."
        autoComplete="off"
        style={{
          flex: 1,
          minWidth: 0,
          padding: '10px 14px',
          background: '#1a1a2e',
          color: '#e0e0e0',
          border: '1px solid #0f3460',
          borderRadius: '6px',
          fontSize: '14px',
        }}
      />
      {/* aria-disabled (not disabled) keeps focus on the button while an answer is pending. */}
      <button
        type="submit"
        aria-disabled={busy}
        style={{
          marginLeft: '10px',
          padding: '10px 20px',
          background: '#533483',
          color: '#fff',
          border: 'none',
          borderRadius: '6px',
          cursor: busy ? 'progress' : 'pointer',
          opacity: busy ? 0.6 : 1,
          fontSize: '14px',
          fontWeight: 500,
        }}
      >
        {busy ? 'Answering…' : 'Ask'}
      </button>
    </form>
  );
}

