// Minimal CDP client (Node 20 + --experimental-websocket). No dependencies.
import fs from 'node:fs';

export async function connect(port = 9333) {
  const list = await (await fetch(`http://localhost:${port}/json/list`)).json();
  const page = list.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  let id = 0;
  const pending = new Map();
  const problems = [];
  ws.onmessage = ev => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const { res, rej } = pending.get(msg.id);
      pending.delete(msg.id);
      msg.error ? rej(new Error(JSON.stringify(msg.error))) : res(msg.result);
    } else if (msg.method === 'Runtime.exceptionThrown') {
      problems.push({ kind: 'exception', text: msg.params.exceptionDetails.exception?.description ?? msg.params.exceptionDetails.text });
    } else if (msg.method === 'Runtime.consoleAPICalled' && (msg.params.type === 'error' || msg.params.type === 'warning')) {
      problems.push({ kind: `console.${msg.params.type}`, text: msg.params.args.map(a => a.value ?? a.description).join(' ') });
    }
  };
  const send = (method, params = {}) => new Promise((res, rej) => {
    const mid = ++id;
    pending.set(mid, { res, rej });
    ws.send(JSON.stringify({ id: mid, method, params }));
  });
  await send('Runtime.enable');
  await send('Page.enable');

  const evaluate = async expression => {
    const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
    if (r.exceptionDetails) throw new Error('evaluate failed: ' + JSON.stringify(r.exceptionDetails));
    return r.result.value;
  };
  const key = async (keyName, opts = {}) => {
    const map = {
      Enter: { code: 'Enter', windowsVirtualKeyCode: 13, text: '\r' },
      Tab: { code: 'Tab', windowsVirtualKeyCode: 9 },
      ' ': { code: 'Space', windowsVirtualKeyCode: 32, text: ' ' },
    };
    const k = map[keyName];
    const modifiers = opts.shift ? 8 : 0;
    await send('Input.dispatchKeyEvent', { type: k.text ? 'keyDown' : 'rawKeyDown', key: keyName, modifiers, ...k });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: keyName, modifiers, code: k.code, windowsVirtualKeyCode: k.windowsVirtualKeyCode });
  };
  const type = text => send('Input.insertText', { text });
  const clickAt = async (x, y) => {
    await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y });
    await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 });
    await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 });
  };
  /** Clicks the centre of the element returned by a JS expression (scrolling it into view first). */
  const click = async selectorExpr => {
    const r = await evaluate(`(() => { const el = ${selectorExpr}; if (!el) return null; el.scrollIntoView({block:'center'}); const b = el.getBoundingClientRect(); return {x: b.x + b.width/2, y: b.y + Math.min(b.height/2, 10)}; })()`);
    if (!r) throw new Error('click target not found: ' + selectorExpr);
    await clickAt(r.x, r.y);
  };
  const screenshot = async file => {
    const r = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(file, Buffer.from(r.data, 'base64'));
  };
  const waitFor = async (expr, timeout = 5000) => {
    const t0 = Date.now();
    while (Date.now() - t0 < timeout) {
      if (await evaluate(expr)) return true;
      await new Promise(r => setTimeout(r, 50));
    }
    throw new Error('timeout waiting for: ' + expr);
  };
  return { send, evaluate, key, type, click, screenshot, waitFor, problems, close: () => ws.close() };
}

